// ICSE 10 Mathematics ch05 Quadratic Equations in One Variable — practice bank with independent re-solve checks.
// Keys, roots, discriminants and rounded values are typed as literals here; each check recomputes them with
// quad.mjs (exact roots, verified by integer substitution; rounding that refuses boundary cases), and every
// typed working line in a solution or model answer is verified by work.mjs (same roots as the verified
// quadratic, true arithmetic, correct roundings). Word-problem answers are also substituted into the story.
import { Q, mk, r, f, plot, geom } from './lib.mjs';
import { Qd, dp, sf, equalRootParams, coeffsOf } from './quad.mjs';
import { steps, texToExpr, ARITH } from './work.mjs';

const J = (lines) => lines.join('\n\n');
const W = (ctx, lines) => steps(ctx, lines);
const ctxOf = (q, roots, v = 'x') => ({ q, roots, v });
const near = (u, w) => Math.abs(u - w) < 1e-9;
/** Degree of L − R for an equation "L = R" typed in TeX (0–4). */
export function degreeOf(eq) {
  const [L, R] = eq.split('=').map((s) => f(texToExpr(s)));
  let y = [0, 1, 2, 3, 4, 5].map((t) => L(t) - R(t));
  let deg = -1;
  for (let k = 0; k <= 5; k++) { if (y.some((t) => Math.abs(t) > 1e-9)) deg = k; y = y.slice(1).map((t, i) => t - y[i]); }
  return deg;
}
const sortP = (p) => [...p].sort((u, w) => u - w);

// =============================================================== MCQ
const o01 = [r`x(x + 3) = 2x - 5`, r`(x - 1)^2 = x^2 + 4`, r`x^3 + 2x = 5`, r`(x + 2)(x - 2) = x^2 - 3x`];
Q('m01', mk.mcq({ stem: r`Which of these becomes a quadratic equation in $x$ when it is simplified and written in the form $ax^2 + bx + c = 0$?`, opts: o01.map((t) => `$${t}$`), key: 'a', sol: r`(a) simplifies to $x^2 + x + 5 = 0$, which has degree $2$. In (b) and (d) the $x^2$ terms cancel and a linear equation is left; (c) has degree $3$.`, d: 1, c: 'recall', t: [1], time: 60 }), (C) => { W(Qd(1, 1, 5), [r`x(x + 3) = 2x - 5`, r`x^2 + x + 5 = 0`]).verify(C); C.which(o01.map(degreeOf), 2); });

const e02 = Qd(1, 1, -12);
Q('m02', mk.mcq({ stem: r`Substitute each value in turn into $x^2 + x - 12 = 0$. Which value is a root?`, opts: ['$3$', '$-3$', '$4$', '$2$'], key: 'a', sol: r`$3^2 + 3 - 12 = 0$. For $-3$ the left side is $-6$, for $4$ it is $8$ and for $2$ it is $-6$. (The other root is $-4$.)`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { W(ARITH, [r`3^2 + 3 - 12 = 0`, r`(-3)^2 - 3 - 12 = -6`, r`4^2 + 4 - 12 = 8`, r`2^2 + 2 - 12 = -6`]).verify(C); C.which([3, -3, 4, 2].map((v) => (e02.roots.some((x) => near(x, v)) ? 'root' : 'no')), 'root'); C.assert(e02.roots.includes(-4), 'other root -4'); });

const e03 = Qd(4, -4, -15);
const o03 = [[-10, 6], [10, -6], [-12, 5], [-15, 4]];
Q('m03', mk.mcq({ stem: r`To factorise $4x^2 - 4x - 15$ by splitting the middle term, you need two numbers whose product is $4 \times (-15) = -60$ and whose sum is $-4$. Which pair works?`, opts: o03.map(([p, q]) => `$${p}$ and $${q}$`), key: 'a', sol: r`$-10 \times 6 = -60$ and $-10 + 6 = -4$. Then $4x^2 - 10x + 6x - 15 = 2x(2x - 5) + 3(2x - 5) = (2x + 3)(2x - 5)$. Option (b) has the right product but the sum $+4$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { W(e03, [r`4x^2 - 10x + 6x - 15 = 2x(2x - 5) + 3(2x - 5) = (2x + 3)(2x - 5)`]).verify(C); C.assert(e03.a * e03.c === -60 && e03.b === -4, 'ac = -60, b = -4'); C.which(o03.map(([p, q]) => `${p * q === e03.a * e03.c && p + q === e03.b}`), 'true'); });

const e04 = Qd(2, -1, -15);
const o04 = [[3, -5 / 2], [-3, 5 / 2], [3, -2 / 5], [3, 5 / 2]];
Q('m04', mk.mcq({ stem: r`What is the solution set of $(x - 3)(2x + 5) = 0$?`, opts: [r`\left\{3, -\dfrac{5}{2}\right\}`, r`\left\{-3, \dfrac{5}{2}\right\}`, r`\left\{3, -\dfrac{2}{5}\right\}`, r`\left\{3, \dfrac{5}{2}\right\}`].map((t) => `$${t}$`), key: 'a', sol: r`A product is zero only when a factor is zero: $x - 3 = 0$ gives $x = 3$, and $2x + 5 = 0$ gives $x = -\dfrac{5}{2}$. Option (b) has both signs wrong; (c) turns $\dfrac{5}{2}$ upside down.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { W(e04, [r`(x - 3)(2x + 5) = 0`, r`x = 3 \text{ or } x = -\dfrac{5}{2}`]).verify(C); C.which(o04.map(sortP), e04.roots); });

const e05 = Qd(6, 1, -15);
const o05 = [[3 / 2, -5 / 3], [-3 / 2, 5 / 3], [3 / 2, 5 / 3], [2 / 3, -3 / 5]];
Q('m05', mk.mcq({ stem: r`Factorising $6x^2 + x - 15 = 0$ gives its roots as`, opts: [r`\dfrac{3}{2} \text{ and } -\dfrac{5}{3}`, r`-\dfrac{3}{2} \text{ and } \dfrac{5}{3}`, r`\dfrac{3}{2} \text{ and } \dfrac{5}{3}`, r`\dfrac{2}{3} \text{ and } -\dfrac{3}{5}`].map((t) => `$${t}$`), key: 'a', sol: r`Product $6 \times (-15) = -90$, sum $1$: use $10$ and $-9$. $6x^2 + 10x - 9x - 15 = 2x(3x + 5) - 3(3x + 5) = (2x - 3)(3x + 5)$, so $x = \dfrac{3}{2}$ or $x = -\dfrac{5}{3}$. Option (d) inverts each root.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { W(e05, [r`6x^2 + 10x - 9x - 15 = 2x(3x + 5) - 3(3x + 5) = (2x - 3)(3x + 5)`]).verify(C); C.which(o05.map(sortP), e05.roots); });

const o06 = [[4, 7, -3], [4, -7, 3], [4, 7, 3], [4, -7, -3]];
Q('m06', mk.mcq({ stem: r`Before using the quadratic formula on $4x^2 = 3 - 7x$, you rewrite it in standard form. What are $a$, $b$ and $c$?`, opts: o06.map(([a, b, c]) => `$a = ${a},\\ b = ${b},\\ c = ${c}$`), key: 'a', sol: r`Move every term to the left: $4x^2 + 7x - 3 = 0$, so $a = 4$, $b = 7$ and $c = -3$. Option (b) reads the signs before the terms were moved.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { W(Qd(4, 7, -3), [r`4x^2 = 3 - 7x`, r`4x^2 + 7x - 3 = 0`]).verify(C); C.which(o06, coeffsOf((x) => 4 * x * x - (3 - 7 * x))); });

const e07 = Qd(1, -6, 4);
const R5 = Math.sqrt(5);
const o07 = [[3 - R5, 3 + R5], [-3 - R5, -3 + R5], [3 - 2 * R5, 3 + 2 * R5], [6 - R5, 6 + R5]];
Q('m07', mk.mcq({ stem: r`Applying the quadratic formula to $x^2 - 6x + 4 = 0$ gives the roots`, opts: [r`3 \pm \sqrt{5}`, r`-3 \pm \sqrt{5}`, r`3 \pm 2\sqrt{5}`, r`6 \pm \sqrt{5}`].map((t) => `$${t}$`), key: 'a', sol: r`$D = 36 - 16 = 20$ and $\sqrt{20} = 2\sqrt{5}$, so $x = \dfrac{6 \pm 2\sqrt{5}}{2} = 3 \pm \sqrt{5}$. Option (c) forgets to divide $2\sqrt{5}$ by $2$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { W(e07, [r`x = \dfrac{6 \pm 2\sqrt{5}}{2} = 3 \pm \sqrt{5}`]).verify(C); W(ARITH, [r`D = 36 - 16 = 20`, r`\sqrt{20} = 2\sqrt{5}`]).verify(C); C.assert(e07.pmTex === r`3 \pm \sqrt{5}`, 'pm form'); C.which(o07, e07.roots); });

const e08 = Qd(1, -3, -5);
Q('m08', mk.mcq({ stem: r`Correct to two decimal places, what is the larger root of $x^2 - 3x - 5 = 0$?`, opts: ['$4.19$', '$4.20$', '$-1.19$', '$4.18$'], key: 'a', sol: r`$x = \dfrac{3 \pm \sqrt{29}}{2}$ and $\sqrt{29} \approx 5.3852$, so the larger root is $\dfrac{3 + 5.3852}{2} \approx 4.1926$, which is $4.19$. Option (b) comes from rounding $\sqrt{29}$ too early, to $5.39$; (c) is the smaller root.`, d: 3, c: 'application', t: [3], time: 90 }), (C) => { W(e08, [r`x = \dfrac{3 \pm \sqrt{29}}{2}`]).verify(C); W(ARITH, [r`\sqrt{29} \approx 5.3852`, r`\dfrac{3 + 5.3852}{2} \approx 4.1926`]).verify(C); C.assert(dp(e08.roots[0], 2) === '-1.19' && (3 + 5.39) / 2 > 4.1949, 'distractors'); C.which([4.19, 4.2, -1.19, 4.18], Number(dp(e08.roots[1], 2))); });

const e09 = Qd(2, 3, -7);
Q('m09', mk.mcq({ stem: r`The positive root of $2x^2 + 3x - 7 = 0$, correct to three significant figures, is`, opts: ['$1.27$', '$1.26$', '$1.266$', '$2.53$'], key: 'a', sol: r`$x = \dfrac{-3 + \sqrt{65}}{4}$ and $\sqrt{65} \approx 8.0623$, so $x \approx 1.2656$, which is $1.27$ to three significant figures. Option (c) has four significant figures; (d) divides by $2$ instead of $2a = 4$.`, d: 3, c: 'understanding', t: [3], time: 90 }), (C) => { W(ARITH, [r`\sqrt{65} \approx 8.0623`, r`\dfrac{-3 + 8.0623}{4} \approx 1.2656`]).verify(C); C.assert(sf((-3 + Math.sqrt(65)) / 2, 3) === '2.53', '(d) = 2.53'); C.which([1.27, 1.26, 1.266, 2.53], Number(sf(e09.roots[1], 3))); });

const e10 = Qd(5, -2, -3);
Q('m10', mk.mcq({ stem: r`What is the value of the discriminant of $5x^2 - 2x - 3 = 0$?`, opts: ['$64$', '$-56$', '$56$', '$8$'], key: 'a', sol: r`$D = (-2)^2 - 4 \times 5 \times (-3) = 4 + 60 = 64$. Option (b) treats $c$ as $+3$; (d) is $\sqrt{D}$.`, d: 2, c: 'understanding', t: [1], time: 45 }), (C) => { W(ARITH, [r`D = (-2)^2 - 4 \times 5 \times (-3) = 4 + 60 = 64`]).verify(C); C.which([64, -56, 56, 8], e10.D); });

const e11 = Qd(9, -6, 1);
Q('m11', mk.mcq({ stem: r`Without solving, decide the nature of the roots of $9x^2 - 6x + 1 = 0$.`, opts: ['real and equal', 'real and distinct', 'not real', 'real, distinct and irrational'], key: 'a', sol: r`$D = (-6)^2 - 4 \times 9 \times 1 = 36 - 36 = 0$, so the roots are real and equal (both $\dfrac{1}{3}$).`, d: 2, c: 'understanding', t: [1], time: 45 }), (C) => { W(ARITH, [r`D = (-6)^2 - 4 \times 9 \times 1 = 36 - 36 = 0`]).verify(C); C.assert(e11.exact[0].tex === r`\dfrac{1}{3}`, 'root 1/3'); C.which(['equal', 'distinct', 'none', 'distinct-irrational'], e11.nature); });

const k12 = equalRootParams((k) => 144 - 16 * k);
Q('m12', mk.mcq({ stem: r`If $kx^2 + 12x + 4 = 0$ has two equal real roots, then $k$ equals`, opts: ['$9$', '$3$', '$-9$', '$36$'], key: 'a', sol: r`Equal roots need $b^2 - 4ac = 0$: $144 - 16k = 0$, so $k = 9$. Option (d) uses $b^2 = 4k$ without the $c$.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => { W(ctxOf(null, [9], 'k'), [r`144 - 16k = 0`, r`k = 9`]).verify(C); C.assert(Qd(9, 12, 4).nature === 'equal', 'k = 9 gives equal roots'); C.which([9, 3, -9, 36], k12.length === 1 ? k12[0].val : NaN); });

const p13 = [(p) => -6 < p && p < 6, (p) => p > 6, (p) => p < -6 || p > 6, (p) => Math.abs(p) === 6];
Q('m13', mk.mcq({ stem: r`For which values of $p$ does $x^2 + px + 9 = 0$ have no real roots?`, opts: [r`-6 < p < 6`, r`p > 6`, r`p < -6 \text{ or } p > 6`, r`p = \pm 6`].map((t) => `$${t}$`), key: 'a', sol: r`No real roots when $p^2 - 36 < 0$, that is $p^2 < 36$, so $-6 < p < 6$. Option (c) is the condition for two distinct real roots, and (d) for equal roots.`, d: 3, c: 'analysis', t: [1], time: 75 }), (C) => { const grid = Array.from({ length: 81 }, (_, i) => -10 + i / 4); const truth = (p) => Qd(4, Math.round(4 * p), 36).nature === 'none'; /* 4(x^2 + px + 9) keeps integer coefficients on the quarter grid */ const ok = (P) => grid.every((p) => P(p) === truth(p)); C.which(p13.map((P) => (ok(P) ? 'yes' : 'no')), 'yes'); });

const p14 = [(c) => c <= 1 / 3, (c) => c >= 1 / 3, (c) => c < 1 / 3, (c) => c <= 3];
Q('m14', mk.mcq({ stem: r`Which condition on the constant $c$ makes both roots of $3x^2 + 2x + c = 0$ real numbers?`, opts: [r`c \le \dfrac{1}{3}`, r`c \ge \dfrac{1}{3}`, r`c < \dfrac{1}{3}`, r`c \le 3`].map((t) => `$${t}$`), key: 'a', sol: r`Real roots need $D \ge 0$: $4 - 12c \ge 0$, so $c \le \dfrac{1}{3}$. Option (c) leaves out $c = \dfrac{1}{3}$, which gives equal (and so real) roots.`, d: 3, c: 'analysis', t: [1], time: 75 }), (C) => { const grid = Array.from({ length: 49 }, (_, i) => i - 12); /* c = i/6; 6(3x^2 + 2x + c) = 18x^2 + 12x + i */ C.which(p14.map((P) => (grid.every((i) => P(i / 6) === (Qd(18, 12, i).nature !== 'none')) ? 'yes' : 'no')), 'yes'); C.assert(Qd(3, 2, 0).nature === 'distinct' && Qd(9, 6, 1).nature === 'equal', 'c = 1/3 gives equal roots'); });

const e15 = Qd(1, 3, -108);
Q('m15', mk.mcq({ stem: r`One positive number is $3$ more than another, and their product is $108$. What is the smaller number?`, opts: ['$9$', '$12$', '$-12$', '$6$'], key: 'a', sol: r`$x(x + 3) = 108 \Rightarrow x^2 + 3x - 108 = 0 \Rightarrow (x + 12)(x - 9) = 0$. The numbers are positive, so $x = 9$ (and the other number is $12$).`, d: 2, c: 'application', t: [4], time: 75 }), (C) => { W(e15, [r`x(x + 3) = 108 \Rightarrow x^2 + 3x - 108 = 0 \Rightarrow (x + 12)(x - 9) = 0`]).verify(C); C.assert(9 * 12 === 108, 'story'); C.which([9, 12, -12, 6], e15.roots.find((x) => x > 0)); });

const e16 = Qd(1, 4, -96, 'b');
Q('m16', mk.mcq({ stem: r`The breadth $b$ metres of a rectangular plot satisfies $b^2 + 4b - 96 = 0$. What is the breadth?`, opts: ['$8$ m', '$-12$ m', '$8$ m or $-12$ m', '$12$ m'], key: 'a', sol: r`$b^2 + 4b - 96 = (b + 12)(b - 8) = 0$, so $b = 8$ or $b = -12$. A breadth cannot be negative, so the breadth is $8$ m.`, d: 2, c: 'application', t: [4], time: 60 }), (C) => { W(e16, [r`b^2 + 4b - 96 = (b + 12)(b - 8)`, r`b = 8 \text{ or } b = -12`]).verify(C); C.which(['8', '-12', '8|-12', '12'], e16.roots.filter((x) => x > 0).join('|')); });

const e17 = Qd(1, 5, -150);
Q('m17', mk.mcq({ stem: r`An imagined cyclist rides $30$ km at a steady speed. Had she ridden $5$ km/h faster, the ride would have taken $1$ hour less. What was her speed?`, opts: ['$10$ km/h', '$15$ km/h', '$5$ km/h', '$6$ km/h'], key: 'a', sol: r`$\dfrac{30}{x} - \dfrac{30}{x + 5} = 1$ gives $x^2 + 5x - 150 = 0$, that is $(x + 15)(x - 10) = 0$. Speed is positive, so $x = 10$. Check: $3$ hours at $10$ km/h, $2$ hours at $15$ km/h. Option (b) is the faster speed.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { W(e17, [r`\dfrac{30}{x} - \dfrac{30}{x + 5} = 1`, r`x^2 + 5x - 150 = 0`, r`(x + 15)(x - 10) = 0`]).verify(C); C.assert(30 / 10 - 30 / 15 === 1, 'story'); C.which([10, 15, 5, 6], e17.roots.find((x) => x > 0)); });

const e18 = Qd(1, -7, 0);
Q('m18', mk.mcq({ stem: r`Kabir solved $x^2 - 7x = 0$ by dividing both sides by $x$, and wrote "$x = 7$". What is wrong with his answer?`, opts: [r`He lost the root $x = 0$.`, r`He lost the root $x = -7$.`, r`Nothing: $7$ is the only root.`, r`The root should be $-7$, not $7$.`], key: 'a', sol: r`$x^2 - 7x = x(x - 7) = 0$ gives $x = 0$ or $x = 7$. Dividing by $x$ assumes $x \ne 0$, so the root $0$ is lost. Take every term to one side and factorise instead.`, d: 2, c: 'analysis', t: [2], time: 60 }), (C) => { W(e18, [r`x^2 - 7x = x(x - 7)`, r`x = 0 \text{ or } x = 7`]).verify(C); C.which(['0', '-7', 'none', 'sign'], e18.roots.filter((x) => !near(x, 7)).join(',')); });

const e19 = Qd(1, -3, -10);
const fig19 = plot({ x: [-4, 7], y: [-14, 10], fns: [{ expr: 'x^2 - 3x - 10' }], pts: [[-2, 0, '(−2, 0)'], [5, 0, '(5, 0)']] }, 'Graph of an upward parabola y equals x squared plus b x plus c, crossing the x-axis at the marked points minus 2 and 5, with its lowest point between them.', 'The two marked points are where $y = 0$.');
const o19 = [[1, -3, -10], [1, 3, -10], [1, -7, 10], [1, 7, 10]];
Q('m19', mk.mcq({ stem: r`The graph of $y = x^2 + bx + c$ crosses the $x$-axis at the two points marked. Which equation has these two roots?`, opts: o19.map(([a, b, c]) => `$${Qd(a, b, c).tex} = 0$`), key: 'a', sol: r`The roots are $-2$ and $5$, so the equation is $(x + 2)(x - 5) = 0$, that is $x^2 - 3x - 10 = 0$. Option (b) has roots $2$ and $-5$; (c) has $2$ and $5$.`, d: 3, c: 'analysis', t: [2], time: 75, assets: [fig19] }), (C) => { W(e19, [r`(x + 2)(x - 5) = 0`]).verify(C); C.which(o19.map(([a, b, c]) => Qd(a, b, c).roots), [-2, 5]); C.assert(near(e19.roots[0], -2) && near(e19.roots[1], 5), 'marked points are the roots'); });

// =============================================================== assertion-reason (keys a d b a d c)
Q('ar1', mk.ar({ a: r`The equation $x^2 - 4x + 7 = 0$ has no real roots.`, r: r`For $x^2 - 4x + 7 = 0$, the value of $b^2 - 4ac$ is negative.`, key: 'a', sol: r`$b^2 - 4ac = 16 - 28 = -12 < 0$, so there are no real roots. Both are true, and R explains A.`, d: 2, c: 'understanding', t: [1] }), (C) => { const e = Qd(1, -4, 7); W(ARITH, [r`16 - 28 = -12`]).verify(C); C.assert(e.D === -12 && e.nature === 'none', 'D = -12, no real roots'); C.key('a'); });
Q('ar2', mk.ar({ a: r`The roots of $(x - 5)(x + 1) = 7$ are $5$ and $-1$.`, r: 'If the product of two numbers is zero, at least one of the numbers is zero.', key: 'd', sol: r`A is false: $x = 5$ makes the left side $0$, not $7$. The right side must be $0$ before the factors are used: $x^2 - 4x - 12 = 0 \Rightarrow (x - 6)(x + 2) = 0$, so the roots are $6$ and $-2$. R is true.`, d: 3, c: 'understanding', t: [2] }), (C) => { const e = Qd(1, -4, -12); W(e, [r`(x - 5)(x + 1) = 7`, r`x^2 - 4x - 12 = 0 \Rightarrow (x - 6)(x + 2) = 0`]).verify(C); C.assert((5 - 5) * (5 + 1) !== 7 && near(e.roots[0], -2) && near(e.roots[1], 6), 'A false'); C.key('d'); });
Q('ar3', mk.ar({ a: r`The roots of $2x^2 - 5x - 1 = 0$ are irrational.`, r: r`In $2x^2 - 5x - 1 = 0$, the coefficients $a$ and $c$ have opposite signs.`, key: 'b', sol: r`$D = 25 + 8 = 33$, which is not a perfect square, so the roots are irrational: A is true. R is true too, but opposite signs of $a$ and $c$ only show that the roots are real; they do not explain why they are irrational.`, d: 3, c: 'understanding', t: [3] }), (C) => { const e = Qd(2, -5, -1); W(ARITH, [r`D = 25 + 8 = 33`]).verify(C); C.assert(e.D === 33 && !e.rational && e.a * e.c < 0, 'A true, R true'); C.key('b'); });
Q('ar4', mk.ar({ a: r`When $k = 8$, the equation $x^2 + kx + 16 = 0$ has equal roots.`, r: r`A quadratic equation $ax^2 + bx + c = 0$ has equal roots when $b^2 = 4ac$.`, key: 'a', sol: r`With $k = 8$: $b^2 = 64$ and $4ac = 4 \times 1 \times 16 = 64$, so the roots are equal (both $-4$). R is exactly the condition used.`, d: 2, c: 'understanding', t: [1] }), (C) => { const e = Qd(1, 8, 16); W(ARITH, [r`4 \times 1 \times 16 = 64`]).verify(C); C.assert(e.nature === 'equal' && e.roots[0] === -4, 'equal root -4'); C.key('a'); });
Q('ar5', mk.ar({ a: r`For an imagined ball thrown up from a balcony, the time $t$ seconds at which it lands satisfies $5t^2 - 10t - 15 = 0$; so the ball lands at $t = 3$ and also at $t = -1$.`, r: 'Time measured from the moment of the throw cannot be negative.', key: 'd', sol: r`$5t^2 - 10t - 15 = 5(t - 3)(t + 1)$, so $t = 3$ or $t = -1$. Because of R, $t = -1$ is rejected: the ball lands only at $t = 3$ s. A is false and R is true.`, d: 3, c: 'application', t: [4] }), (C) => { const e = Qd(5, -10, -15, 't'); W(e, [r`5t^2 - 10t - 15 = 5(t - 3)(t + 1)`, r`t = 3 \text{ or } t = -1`]).verify(C); C.assert(e.roots.filter((x) => x >= 0).length === 1, 'one admissible time'); C.key('d'); });
Q('ar6', mk.ar({ a: r`Correct to one decimal place, the positive root of $x^2 - 2 = 0$ is $1.4$.`, r: 'Every quadratic equation has two distinct real roots.', key: 'c', sol: r`$x = \sqrt{2} = 1.414\ldots$, so A is true. R is false: $x^2 + 1 = 0$ has no real roots and $x^2 - 2x + 1 = 0$ has equal roots.`, d: 2, c: 'understanding', t: [3] }), (C) => { const e = Qd(1, 0, -2); C.assert(dp(e.roots[1], 1) === '1.4' && Qd(1, 0, 1).nature === 'none' && Qd(1, -2, 1).nature === 'equal', 'A true, R false'); C.key('c'); });

// =============================================================== true-false
const e_tf1 = Qd(5, -20, 0);
Q('tf1', mk.tf({ stem: r`Dividing both sides of $5x^2 = 20x$ by $x$ gives every root of the equation.`, key: 'f', sol: r`Dividing by $x$ loses the root $0$. Instead, $5x^2 - 20x = 0 \Rightarrow 5x(x - 4) = 0$, so $x = 0$ or $x = 4$.`, d: 2, c: 'understanding', t: [2] }), (C) => { W(e_tf1, [r`5x^2 - 20x = 0 \Rightarrow 5x(x - 4) = 0`, r`x = 0 \text{ or } x = 4`]).verify(C); C.assert(e_tf1.roots.length === 2 && e_tf1.roots.includes(0), 'two roots including 0'); C.key('f'); });
Q('tf2', mk.tf({ stem: r`If $b^2 - 4ac > 0$, the equation $ax^2 + bx + c = 0$ (with $a \ne 0$) has two distinct real roots.`, key: 't', sol: r`A positive discriminant has two different square roots, $\pm\sqrt{b^2 - 4ac}$, so the formula gives two different real roots.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert([[1, -5, 6], [2, 1, -3], [3, 7, 1]].every(([a, b, c]) => Qd(a, b, c).roots.length === 2), 'D > 0 examples give two roots'); C.key('t'); });
Q('tf3', mk.tf({ stem: r`The roots of $x^2 - 2x - 2 = 0$ are $1 + \sqrt{3}$ and $1 - \sqrt{3}$.`, key: 't', sol: r`$D = 4 + 8 = 12$ and $\sqrt{12} = 2\sqrt{3}$, so $x = \dfrac{2 \pm 2\sqrt{3}}{2} = 1 \pm \sqrt{3}$.`, d: 2, c: 'understanding', t: [3] }), (C) => { const e = Qd(1, -2, -2); W(e, [r`x = \dfrac{2 \pm 2\sqrt{3}}{2} = 1 \pm \sqrt{3}`]).verify(C); C.assert(e.pmTex === r`1 \pm \sqrt{3}`, 'roots 1 ± √3'); C.key('t'); });
Q('tf4', mk.tf({ stem: r`When $(x + 3)^2 = x^2 + 1$ is simplified, it becomes a quadratic equation.`, key: 'f', sol: r`$x^2 + 6x + 9 = x^2 + 1$; the $x^2$ terms cancel and $6x + 8 = 0$ is left, which is linear.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(degreeOf(r`(x + 3)^2 = x^2 + 1`) === 1 && degreeOf(r`x^2 + 6x + 9 = x^2 + 1`) === 1, 'linear'); C.key('f'); });
Q('tf5', mk.tf({ stem: r`In a problem where $x$ stands for the number of students in a class, a root $x = 7.5$ of the equation must be rejected.`, key: 't', sol: 'The number of students must be a whole number, so a fractional root does not fit the problem.', d: 2, c: 'understanding', t: [4] }), (C) => { C.assert(!Number.isInteger(7.5), '7.5 is not a whole number'); C.key('t'); });
Q('tf6', mk.tf({ stem: r`The quadratic formula finds the real roots of any quadratic equation that has them, even when the quadratic cannot be factorised using integers.`, key: 't', sol: r`For example, $x^2 - 3x - 5 = 0$ cannot be factorised using integers, but the formula gives $x = \dfrac{3 \pm \sqrt{29}}{2}$.`, d: 1, c: 'recall', t: [3] }), (C) => { const e = Qd(1, -3, -5); C.assert(!e.rational && e.roots.length === 2 && e.pmTex === r`\dfrac{3 \pm \sqrt{29}}{2}`, 'irrational roots by the formula'); C.key('t'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: r`In the standard form $ax^2 + bx + c = 0$ of a quadratic equation, the coefficient ___ must not be zero.`, acc: [['a', '$a$']], sol: r`The coefficient $a$: if $a = 0$, the $x^2$ term disappears and the equation is linear.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert(degreeOf(r`0x^2 + 3x + 2 = 0`) === 1, 'a = 0 gives a linear equation'); C.blank('a'); });
const kfb2 = equalRootParams((p) => p * p - 16);
Q('fb2', mk.fill({ stem: r`If $4x^2 - px + 1 = 0$ has equal roots and $p > 0$, then $p =$ ___.`, acc: [['4']], sol: r`$p^2 - 4 \times 4 \times 1 = 0$, so $p^2 = 16$ and $p = \pm 4$. As $p > 0$, $p = 4$.`, d: 2, c: 'application', t: [1] }), (C) => { W(ctxOf(null, kfb2.map((k) => k.val), 'p'), [r`p = \pm 4`]).verify(C); C.blank(kfb2.find((k) => k.val > 0).val); });
const efb3 = Qd(1, -9, 14);
Q('fb3', mk.fill({ stem: r`Given that $2$ is one root of $x^2 - 9x + 14 = 0$, its other root is ___.`, acc: [['7']], sol: r`$x^2 - 9x + 14 = (x - 2)(x - 7)$, so the other root is $7$.`, d: 1, c: 'understanding', t: [2] }), (C) => { W(efb3, [r`x^2 - 9x + 14 = (x - 2)(x - 7)`]).verify(C); C.blank(efb3.roots.find((x) => !near(x, 2))); });
Q('fb4', mk.fill({ stem: r`For $x^2 + 3x - 10 = 0$, the value of $b^2 - 4ac$ is ___.`, acc: [['49']], sol: r`$3^2 - 4 \times 1 \times (-10) = 9 + 40 = 49$.`, d: 1, c: 'understanding', t: [1] }), (C) => { W(ARITH, [r`3^2 - 4 \times 1 \times (-10) = 9 + 40 = 49`]).verify(C); C.blank(Qd(1, 3, -10).D); });
const efb5 = Qd(1, 1, -3);
Q('fb5', mk.fill({ stem: r`Correct to one decimal place, the positive root of $x^2 + x - 3 = 0$ is ___.`, acc: [['1.3']], sol: r`$x = \dfrac{-1 + \sqrt{13}}{2}$ and $\sqrt{13} \approx 3.6056$, so $x \approx 1.3028$, which is $1.3$.`, d: 3, c: 'application', t: [3] }), (C) => { W(ARITH, [r`\sqrt{13} \approx 3.6056`, r`\dfrac{-1 + 3.6056}{2} \approx 1.3028`]).verify(C); C.blank(Number(dp(efb5.roots[1], 1))); });
const efb6 = Qd(1, -1, -12);
Q('fb6', mk.fill({ stem: r`A positive number is $12$ less than its own square. The number is ___.`, acc: [['4']], sol: r`$x = x^2 - 12 \Rightarrow x^2 - x - 12 = 0 \Rightarrow (x - 4)(x + 3) = 0$. The number is positive, so it is $4$.`, d: 2, c: 'application', t: [4] }), (C) => { W(efb6, [r`x = x^2 - 12 \Rightarrow x^2 - x - 12 = 0 \Rightarrow (x - 4)(x + 3) = 0`]).verify(C); C.blank(efb6.roots.find((x) => x > 0)); });

// =============================================================== numerical
const en01 = Qd(1, -4, -3);
Q('n01', mk.num({ stem: r`Give the greater root of $x^2 - 4x - 3 = 0$ to two decimal places.`, value: 4.65, sol: r`$x = \dfrac{4 \pm \sqrt{28}}{2} = 2 \pm \sqrt{7}$; with $\sqrt{7} \approx 2.6458$ the greater root is $4.6458$, that is $4.65$.`, scheme: [['4.65', 1]], d: 2, c: 'understanding', t: [3], time: 75 }), (C) => { W(en01, [r`x = \dfrac{4 \pm \sqrt{28}}{2} = 2 \pm \sqrt{7}`]).verify(C); W(ARITH, [r`2 + 2.6458 = 4.6458`, r`\sqrt{7} \approx 2.6458`]).verify(C); C.val(Number(dp(en01.roots[1], 2))); });
Q('n02', mk.num({ stem: r`Calculate $b^2 - 4ac$ for the equation $3x^2 + 5x - 2 = 0$.`, value: 49, sol: r`$5^2 - 4 \times 3 \times (-2) = 25 + 24 = 49$.`, scheme: [['49', 1]], d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { W(ARITH, [r`5^2 - 4 \times 3 \times (-2) = 25 + 24 = 49`]).verify(C); C.val(Qd(3, 5, -2).D); });
const mn03 = equalRootParams((m) => 4 * (m + 1) ** 2 - 36);
Q('n03', mk.num({ marks: 2, stem: r`The roots of $x^2 - 2(m + 1)x + 9 = 0$ are real and equal. What is the positive value of $m$?`, value: 2, sol: r`$4(m + 1)^2 - 36 = 0$, so $(m + 1)^2 = 9$ and $m + 1 = \pm 3$: $m = 2$ or $m = -4$. The positive value is $2$.`, scheme: [['Equal-roots condition (m + 1)² = 9', 1], ['m = 2', 1]], d: 3, c: 'application', t: [1], time: 90 }), (C) => { W(ctxOf(null, mn03.map((k) => k.val), 'm'), [r`4(m + 1)^2 - 36 = 0`, r`m = 2 \text{ or } m = -4`]).verify(C); C.assert(Qd(1, -6, 9).nature === 'equal', 'm = 2 gives x^2 - 6x + 9'); C.val(mn03.find((k) => k.val > 0).val); });
const en04 = Qd(1, -4, -45, 'n');
Q('n04', mk.num({ stem: r`The square of a natural number is $45$ more than four times the number. Find the number.`, value: 9, sol: r`$n^2 = 4n + 45 \Rightarrow n^2 - 4n - 45 = 0 \Rightarrow (n - 9)(n + 5) = 0$. A natural number is positive, so $n = 9$. Check: $81 = 36 + 45$.`, scheme: [['9', 1]], d: 2, c: 'application', t: [4], time: 75 }), (C) => { W(en04, [r`n^2 = 4n + 45 \Rightarrow n^2 - 4n - 45 = 0 \Rightarrow (n - 9)(n + 5) = 0`]).verify(C); W(ARITH, [r`81 = 36 + 45`]).verify(C); C.val(en04.roots.find((x) => x > 0)); });
const en05 = Qd(1, -23, 120);
Q('n05', mk.num({ marks: 2, stem: r`An imagined rectangular hall has a perimeter of $46$ m and a floor area of $120$ m². Find the length of its longer side in metres.`, value: 15, unit: 'm', sol: r`If one side is $x$ m, the other is $(23 - x)$ m, so $x(23 - x) = 120 \Rightarrow x^2 - 23x + 120 = 0 \Rightarrow (x - 8)(x - 15) = 0$. The sides are $8$ m and $15$ m (check: $23 - 8 = 15$); the longer is $15$ m.`, scheme: [['x² − 23x + 120 = 0', 1], ['15 m', 1]], d: 3, c: 'application', t: [4], time: 120 }), (C) => { W(en05, [r`x(23 - x) = 120 \Rightarrow x^2 - 23x + 120 = 0 \Rightarrow (x - 8)(x - 15) = 0`]).verify(C); C.assert(2 * (8 + 15) === 46 && 8 * 15 === 120, 'story'); C.val(Math.max(...en05.roots)); });
const en06 = Qd(1, -14, -120);
Q('n06', mk.num({ marks: 2, stem: r`Two imagined pipes together fill a tank in $12$ minutes. One pipe alone takes $10$ minutes longer than the other. How many minutes does the faster pipe take alone?`, value: 20, unit: 'min', sol: r`If the faster pipe takes $x$ minutes, $\dfrac{1}{x} + \dfrac{1}{x + 10} = \dfrac{1}{12}$, which gives $x^2 - 14x - 120 = 0$, that is $(x - 20)(x + 6) = 0$. Rejecting the negative root, $x = 20$: the faster pipe takes $20$ minutes (and the other $30$).`, scheme: [['x² − 14x − 120 = 0', 1], ['20 minutes', 1]], d: 3, c: 'application', t: [4], time: 150 }), (C) => { W(en06, [r`\dfrac{1}{x} + \dfrac{1}{x + 10} = \dfrac{1}{12}`, r`x^2 - 14x - 120 = 0`, r`(x - 20)(x + 6) = 0`]).verify(C); C.assert(near(1 / 20 + 1 / 30, 1 / 12), 'story'); C.val(en06.roots.find((x) => x > 0)); });
const en07 = Qd(1, -8, 11);
Q('n07', mk.num({ stem: r`Solve $x^2 - 8x + 11 = 0$ and give the smaller root correct to three significant figures.`, value: 1.76, sol: r`$x = \dfrac{8 \pm \sqrt{20}}{2} = 4 \pm \sqrt{5}$. With $\sqrt{5} \approx 2.2361$, the smaller root is $1.7639$, that is $1.76$.`, scheme: [['1.76', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => { W(en07, [r`x = \dfrac{8 \pm \sqrt{20}}{2} = 4 \pm \sqrt{5}`]).verify(C); W(ARITH, [r`\sqrt{5} \approx 2.2361`, r`4 - 2.2361 = 1.7639`]).verify(C); C.val(Number(sf(en07.roots[0], 3))); });

// =============================================================== short, 2 marks
const es201 = Qd(2, -9, 10);
const w201 = W(es201, [r`2x^2 - 4x - 5x + 10 = 0`, r`2x(x - 2) - 5(x - 2) = 0`, r`(x - 2)(2x - 5) = 0`, r`x = 2 \text{ or } x = \dfrac{5}{2}`]);
Q('s201', mk.short({ marks: 2, stem: r`Solve by factorisation: $2x^2 - 9x + 10 = 0$.`, model: J(['Product $2 \\times 10 = 20$ and sum $-9$: use $-4$ and $-5$.', ...w201.md]), sol: 'Split the middle term with two numbers whose product is ac and whose sum is b, then use the zero-product rule.', scheme: [['Middle term split and factorised', 1], ['Both roots', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => { w201.verify(C); C.model([2, 2.5]); });
const es202 = Qd(5, 3, 1);
const w202 = W(ARITH, [r`D = 3^2 - 4 \times 5 \times 1 = 9 - 20 = -11`]);
Q('s202', mk.short({ marks: 2, stem: r`Without solving, state the nature of the roots of $5x^2 + 3x + 1 = 0$. Give a reason.`, model: J([...w202.md, 'Since $D < 0$, the equation has **no real roots**.']), sol: 'Compute the discriminant and compare it with zero.', scheme: [['D = −11', 1], ['No real roots', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { w202.verify(C); C.assert(es202.D === -11 && es202.nature === 'none', 'none'); C.model([-11, 'no real roots']); });
const es203 = Qd(1, 4, -1);
const w203 = W(es203, [r`x = \dfrac{-4 \pm \sqrt{20}}{2} = \dfrac{-4 \pm 2\sqrt{5}}{2} = -2 \pm \sqrt{5}`, r`x = -2 + \sqrt{5} \text{ or } x = -2 - \sqrt{5}`]);
Q('s203', mk.short({ marks: 2, stem: r`Use the quadratic formula to solve $x^2 + 4x - 1 = 0$. Leave the roots in surd form.`, model: J([r`$a = 1$, $b = 4$, $c = -1$; $D = 16 + 4 = 20$.`, ...w203.md]), sol: 'Identify a, b and c with their signs, find the discriminant, substitute in the formula and simplify the surd.', scheme: [['D = 20 and substitution', 1], ['−2 ± √5', 1]], d: 2, c: 'understanding', t: [3], time: 120 }), (C) => { w203.verify(C); W(ARITH, [r`D = 16 + 4 = 20`]).verify(C); C.assert(es203.pmTex === r`-2 \pm \sqrt{5}`, 'pm'); C.model([r`-2 \pm \sqrt{5}`]); });
const es204 = Qd(2, -3, -9);
const w204 = W(es204, [r`2x^2 = 3x + 9`, r`2x^2 - 3x - 9 = 0`, r`2x^2 - 6x + 3x - 9 = 0`, r`2x(x - 3) + 3(x - 3) = 0`, r`(x - 3)(2x + 3) = 0`, r`x = 3 \text{ or } x = -\dfrac{3}{2}`]);
Q('s204', mk.short({ marks: 2, stem: r`Solve $2x^2 = 3(x + 3)$.`, model: J(w204.md), sol: 'Remove the bracket, bring every term to one side, then factorise.', scheme: [['Standard form 2x² − 3x − 9 = 0', 1], ['x = 3 or x = −3/2', 1]], d: 2, c: 'application', t: [2], time: 120 }), (C) => { w204.verify(C); C.model([3, -1.5]); });
const es205 = Qd(2, 1, -21);
const w205 = W(es205, [r`x + 2x^2 = 21`, r`2x^2 + x - 21 = 0`, r`2x^2 + 7x - 6x - 21 = 0`, r`x(2x + 7) - 3(2x + 7) = 0`, r`(2x + 7)(x - 3) = 0`, r`x = 3 \text{ or } x = -\dfrac{7}{2}`]);
Q('s205', mk.short({ marks: 2, stem: r`When a number is added to twice its own square, the result is $21$. Find all such numbers.`, model: J(['Let the number be $x$.', ...w205.md, r`Both values fit (the number need not be positive): the number is $3$ or $-\dfrac{7}{2}$.`]), sol: 'Translate the sentence into an equation, write it in standard form and factorise; keep every root that fits.', scheme: [['Equation 2x² + x − 21 = 0', 1], ['3 and −7/2', 1]], d: 2, c: 'application', t: [4], time: 120 }), (C) => { w205.verify(C); C.assert(3 + 2 * 9 === 21 && -3.5 + 2 * 12.25 === 21, 'story'); C.model([3, 3.5]); });

// =============================================================== short, 3 marks
const es301 = Qd(3, -13, 12);
const w301 = W(es301, [r`\dfrac{1}{x - 2} + \dfrac{2}{x - 1} = \dfrac{6}{x}`, r`x(x - 1) + 2x(x - 2) = 6(x - 1)(x - 2)`, r`3x^2 - 5x = 6x^2 - 18x + 12`, r`3x^2 - 13x + 12 = 0`, r`3x^2 - 9x - 4x + 12 = 0`, r`3x(x - 3) - 4(x - 3) = 0`, r`(3x - 4)(x - 3) = 0`, r`x = 3 \text{ or } x = \dfrac{4}{3}`]);
Q('s301', mk.short({ marks: 3, stem: r`Solve $\dfrac{1}{x - 2} + \dfrac{2}{x - 1} = \dfrac{6}{x}$, where $x \ne 0, 1, 2$.`, model: J([w301.md[0], 'Multiply both sides by $x(x - 1)(x - 2)$:', ...w301.md.slice(1), 'Neither value is $0$, $1$ or $2$, so both are roots.']), sol: 'Clear the fractions with the product of the denominators, simplify to standard form and factorise; check that no root makes a denominator zero.', scheme: [['Fractions cleared', 1], ['3x² − 13x + 12 = 0', 1], ['x = 3 or x = 4/3', 1]], d: 3, c: 'application', t: [2], time: 240 }), (C) => { w301.verify(C); C.assert(near(1 / (4 / 3 - 2) + 2 / (4 / 3 - 1), 6 / (4 / 3)) && near(1 / 1 + 2 / 2, 6 / 3), 'roots satisfy the original'); C.model([3, r`\dfrac{4}{3}`]); });
const es302 = Qd(2, -7, 4);
const w302a = W(ARITH, [r`D = (-7)^2 - 4 \times 2 \times 4 = 49 - 32 = 17`, r`\sqrt{17} \approx 4.1231`, r`\dfrac{7 + 4.1231}{4} \approx 2.7808`, r`\dfrac{7 - 4.1231}{4} \approx 0.7192`]);
const w302 = W(es302, [r`x = \dfrac{7 \pm \sqrt{17}}{4}`, r`x \approx 2.78 \text{ or } x \approx 0.72`]);
Q('s302', mk.short({ marks: 3, stem: r`Solve $2x^2 - 7x + 4 = 0$, giving the roots correct to two decimal places.`, model: J([r`$a = 2$, $b = -7$, $c = 4$.`, w302a.md[0], w302.md[0], ...w302a.md.slice(1), w302.md[1]]), sol: 'Use the formula; keep four decimal places in the square root and round only at the end.', scheme: [['D = 17', 1], ['Formula with correct substitution', 1], ['2.78 and 0.72', 1]], d: 2, c: 'understanding', t: [3], time: 180 }), (C) => { w302a.verify(C); w302.verify(C); C.model([dp(es302.roots[1], 2), dp(es302.roots[0], 2)].map(Number)); });
const k303 = equalRootParams((k) => 16 - 4 * (k - 3));
const es303 = Qd(4, 4, 1);
const w303k = W(ctxOf(null, k303.map((k) => k.val), 'k'), [r`4^2 - 4(k - 3) \times 1 = 0`, r`28 - 4k = 0`, r`k = 7`]);
const w303x = W(es303, [r`4x^2 + 4x + 1 = 0`, r`(2x + 1)^2 = 0`, r`x = -\dfrac{1}{2}`]);
Q('s303', mk.short({ marks: 3, stem: r`For what value of $k$ are the roots of $(k - 3)x^2 + 4x + 1 = 0$ equal? For this value, find the roots.`, model: J(['Equal roots: $b^2 - 4ac = 0$.', ...w303k.md, r`Then $k - 3 = 4 \ne 0$, so the equation is quadratic:`, ...w303x.md, r`Both roots equal $-\dfrac{1}{2}$.`]), sol: 'Put the discriminant equal to zero and solve for k; substitute k back and solve the perfect square.', scheme: [['Discriminant set to zero', 1], ['k = 7', 1], ['Equal roots −1/2', 1]], d: 3, c: 'application', t: [1], time: 180 }), (C) => { w303k.verify(C); w303x.verify(C); C.assert(k303.length === 1 && k303[0].val === 7 && 7 - 3 === 4 && es303.nature === 'equal', 'k = 7, equal roots'); C.model([7, 0.5]); });
const es304 = Qd(1, -44, 340);
const w304 = W(es304, [r`(x - 4)(40 - x) = 180`, r`-x^2 + 44x - 160 = 180`, r`x^2 - 44x + 340 = 0`, r`(x - 10)(x - 34) = 0`, r`x = 10 \text{ or } x = 34`]);
Q('s304', mk.short({ marks: 3, stem: r`The present ages of an imagined mother and her daughter add up to $44$ years. Four years ago, the product of their ages was $180$. Find their present ages.`, model: J([r`Let the daughter be $x$ years old; the mother is $(44 - x)$ years old. Four years ago they were $(x - 4)$ and $(40 - x)$ years old.`, ...w304.md, r`If $x = 34$, the daughter would be $34$ and the mother $10$, which is impossible. So the daughter is $10$ years old and the mother $34$ years old. Check: $6 \times 30 = 180$.`]), sol: 'Express both ages in one unknown, form the product equation, solve, and reject the root that makes the daughter older than her mother.', scheme: [['Equation (x − 4)(40 − x) = 180', 1], ['x = 10 or 34', 1], ['Rejection and ages 10 and 34', 1]], d: 3, c: 'application', t: [4], time: 240 }), (C) => { w304.verify(C); W(ARITH, [r`6 \times 30 = 180`]).verify(C); C.assert((10 - 4) * (34 - 4) === 180 && 10 + 34 === 44, 'story'); C.model([10, 34, 180]); });
const es305 = Qd(4, 4, -1);
const w305a = W(ARITH, [r`D = 4^2 - 4 \times 4 \times (-1) = 16 + 16 = 32`, r`\sqrt{32} \approx 5.6569`, r`\dfrac{-4 + 5.6569}{8} \approx 0.2071`, r`\dfrac{-4 - 5.6569}{8} \approx -1.2071`]);
const w305 = W(es305, [r`x = \dfrac{-4 \pm \sqrt{32}}{8}`, r`x \approx 0.207 \text{ or } x \approx -1.21`]);
Q('s305', mk.short({ marks: 3, stem: r`Solve $4x^2 + 4x - 1 = 0$ by the formula, giving the roots correct to three significant figures.`, model: J([w305a.md[0], w305.md[0], ...w305a.md.slice(1), w305.md[1]]), sol: 'Use the formula, then count significant figures from the first non-zero digit.', scheme: [['D = 32', 1], ['Formula with correct substitution', 1], ['0.207 and −1.21', 1]], d: 3, c: 'understanding', t: [3], time: 180 }), (C) => { w305a.verify(C); w305.verify(C); C.assert(sf(es305.roots[1], 3) === '0.207' && sf(es305.roots[0], 3) === '-1.21', '3 s.f.'); C.model([0.207, 1.21]); });
const es306 = Qd(1, -32, 260);
const es306b = Qd(1, -32, 256);
const w306 = W(es306, [r`x(32 - x) = 260`, r`x^2 - 32x + 260 = 0`]);
const w306d = W(ARITH, [r`D = (-32)^2 - 4 \times 1 \times 260 = 1024 - 1040 = -16`]);
const w306b = W(es306b, [r`x^2 - 32x + 256 = 0`, r`(x - 16)^2 = 0`, r`x = 16`]);
Q('s306', mk.short({ marks: 3, stem: r`An imagined framer has $64$ cm of moulding to make a rectangular photo frame. Show that the frame cannot enclose an area of $260$ cm², and find the greatest area it can enclose.`, model: J([r`If one side is $x$ cm, the other is $(32 - x)$ cm.`, ...w306.md, w306d.md[0], r`$D < 0$, so no real length $x$ exists: an area of $260$ cm² is impossible.`, r`For an area $A$ cm²: $x^2 - 32x + A = 0$ has real roots only if $1024 - 4A \ge 0$, that is $A \le 256$. With $A = 256$:`, ...w306b.md, r`A $16$ cm by $16$ cm square, so the greatest area is $256$ cm².`]), sol: 'Form the area equation and use the sign of the discriminant to decide whether a real side length exists; the boundary case D = 0 gives the largest area.', scheme: [['x² − 32x + 260 = 0', 1], ['D = −16 < 0, so impossible', 1], ['Greatest area 256 cm² from D ≥ 0', 1]], d: 4, c: 'analysis', t: [4, 1], time: 240 }), (C) => { w306.verify(C); w306d.verify(C); w306b.verify(C); C.assert(es306.nature === 'none' && es306b.nature === 'equal' && 1024 / 4 === 256 && Qd(1, -32, 257).nature === 'none' && Qd(1, -32, 255).nature === 'distinct', 'boundary at 256'); C.model([-16, 256, 16]); });

// =============================================================== short, 4 marks
const es401 = Qd(1, 3, -10);
const w401 = W(es401, [r`\dfrac{x + 1}{x - 1} + \dfrac{x - 2}{x + 2} = 3`, r`(x + 1)(x + 2) + (x - 2)(x - 1) = 3(x - 1)(x + 2)`, r`2x^2 + 4 = 3x^2 + 3x - 6`, r`x^2 + 3x - 10 = 0`, r`(x + 5)(x - 2) = 0`, r`x = 2 \text{ or } x = -5`]);
Q('s401', mk.short({ marks: 4, stem: r`Solve $\dfrac{x + 1}{x - 1} + \dfrac{x - 2}{x + 2} = 3$, where $x \ne 1, -2$.`, model: J([w401.md[0], 'Multiply both sides by $(x - 1)(x + 2)$:', ...w401.md.slice(1), 'Neither root is $1$ or $-2$, so both are accepted.']), sol: 'Multiply through by the product of the denominators, expand carefully and collect terms into standard form.', scheme: [['Fractions cleared', 1], ['Expanded and simplified', 1], ['x² + 3x − 10 = 0 factorised', 1], ['x = 2 or x = −5', 1]], d: 3, c: 'application', t: [2], time: 300 }), (C) => { w401.verify(C); C.model([2, -5]); });
const es402 = Qd(1, -2, -6);
const w402 = W(es402, [r`\dfrac{x^2}{2} - x - 3 = 0`, r`x^2 - 2x - 6 = 0`, r`x = \dfrac{2 \pm \sqrt{28}}{2} = 1 \pm \sqrt{7}`, r`x \approx 3.65 \text{ or } x \approx -1.65`]);
const w402a = W(ARITH, [r`D = (-2)^2 - 4 \times 1 \times (-6) = 4 + 24 = 28`, r`\sqrt{7} \approx 2.6458`, r`1 + 2.6458 = 3.6458 \approx 3.65`, r`1 - 2.6458 = -1.6458 \approx -1.65`]);
Q('s402', mk.short({ marks: 4, stem: r`Solve $\dfrac{x^2}{2} - x - 3 = 0$ and give the roots correct to two decimal places.`, model: J([w402.md[0], 'Multiply by $2$:', w402.md[1], w402a.md[0], w402.md[2], ...w402a.md.slice(1), w402.md[3]]), sol: 'Clear the fraction first so that a, b and c are integers, then use the formula and round at the end.', scheme: [['Fraction cleared: x² − 2x − 6 = 0', 1], ['D = 28', 1], ['1 ± √7', 1], ['3.65 and −1.65', 1]], d: 3, c: 'application', t: [3], time: 240 }), (C) => { w402.verify(C); w402a.verify(C); C.model([3.65, 1.65]); });
const k403 = equalRootParams((k) => 4 * k * k - 4 * (7 * k - 12));
const w403k = W(Object.assign(Qd(1, -7, 12, 'k')), [r`(-2k)^2 - 4(7k - 12) = 0`, r`4k^2 - 28k + 48 = 0`, r`k^2 - 7k + 12 = 0`, r`(k - 3)(k - 4) = 0`, r`k = 3 \text{ or } k = 4`]);
const w403a = W(Qd(1, -6, 9), [r`x^2 - 6x + 9 = 0`, r`(x - 3)^2 = 0`, r`x = 3`]);
const w403b = W(Qd(1, -8, 16), [r`x^2 - 8x + 16 = 0`, r`(x - 4)^2 = 0`, r`x = 4`]);
Q('s403', mk.short({ marks: 4, stem: r`Find the values of $k$ for which the roots of $x^2 - 2kx + 7k - 12 = 0$ are equal. For each value, find the equal roots.`, model: J(['Equal roots: $b^2 - 4ac = 0$ with $a = 1$, $b = -2k$, $c = 7k - 12$.', ...w403k.md, '**When $k = 3$:**', ...w403a.md, '**When $k = 4$:**', ...w403b.md]), sol: 'The equal-roots condition gives a quadratic in k; solve it, then substitute each k back.', scheme: [['Discriminant in terms of k set to zero', 1], ['k = 3 or k = 4', 1], ['k = 3: root 3', 1], ['k = 4: root 4', 1]], d: 4, c: 'application', t: [1], time: 300 }), (C) => { w403k.verify(C); w403a.verify(C); w403b.verify(C); C.assert(k403.map((k) => k.val).join() === '3,4' && 2 * 3 === 6 && 7 * 3 - 12 === 9 && 2 * 4 === 8 && 7 * 4 - 12 === 16, 'k values and substituted equations'); C.model([3, 4]); });
const es404 = Qd(1, 10, -2000);
const w404 = W(es404, [r`\dfrac{200}{x} - \dfrac{200}{x + 10} = 1`, r`200(x + 10) - 200x = x(x + 10)`, r`x^2 + 10x - 2000 = 0`, r`(x + 50)(x - 40) = 0`, r`x = 40 \text{ or } x = -50`]);
Q('s404', mk.short({ marks: 4, stem: r`An imagined goods truck covers $200$ km at a uniform speed. If its speed were $10$ km/h more, the journey would take $1$ hour less. Find its speed.`, model: J([r`Let the speed be $x$ km/h. The time is $\dfrac{200}{x}$ hours, and at the higher speed $\dfrac{200}{x + 10}$ hours.`, ...w404.md, r`A speed cannot be negative, so the speed is $40$ km/h. Check: $5$ hours at $40$ km/h and $4$ hours at $50$ km/h.`]), sol: 'Write each time as distance over speed; their difference is 1 hour. Reject the negative speed.', scheme: [['Time equation', 1], ['x² + 10x − 2000 = 0', 1], ['Factorised: x = 40 or −50', 1], ['Reject −50; 40 km/h', 1]], d: 3, c: 'application', t: [4], time: 300 }), (C) => { w404.verify(C); C.assert(200 / 40 - 200 / 50 === 1, 'story'); C.model([40, 50]); });
const es405 = Qd(1, -2, -24);
const w405 = W(es405, [r`\dfrac{1}{x} + \dfrac{1}{x + 6} = \dfrac{1}{4}`, r`4(x + 6) + 4x = x(x + 6)`, r`x^2 - 2x - 24 = 0`, r`(x - 6)(x + 4) = 0`, r`x = 6 \text{ or } x = -4`]);
Q('s405', mk.short({ marks: 4, stem: r`Working together, two imagined painters can paint a wall in $4$ hours. Working alone, Rina takes $6$ hours longer than Sohan. How long does each take alone?`, model: J([r`Let Sohan take $x$ hours; Rina takes $(x + 6)$ hours. In one hour they paint $\dfrac{1}{x}$ and $\dfrac{1}{x + 6}$ of the wall.`, ...w405.md, r`Time cannot be negative, so Sohan takes $6$ hours and Rina $12$ hours. Check: $\dfrac{1}{6} + \dfrac{1}{12} = \dfrac{1}{4}$.`]), sol: 'Add the work done in one hour by each painter and equate it to the joint rate; reject the negative time.', scheme: [['Rate equation', 1], ['x² − 2x − 24 = 0', 1], ['x = 6 or −4', 1], ['Sohan 6 h, Rina 12 h', 1]], d: 3, c: 'application', t: [4], time: 300 }), (C) => { w405.verify(C); W(ARITH, [r`\dfrac{1}{6} + \dfrac{1}{12} = \dfrac{1}{4}`]).verify(C); C.model([6, 12]); });
const es406 = Qd(2, -10, 12);
const w406 = W(es406, [r`(x - 3)(2x + 1) - 5(x - 3) = 0`, r`(x - 3)(2x + 1 - 5) = 0`, r`(x - 3)(2x - 4) = 0`, r`x = 3 \text{ or } x = 2`]);
Q('s406', mk.short({ marks: 4, stem: r`Asha solved $(x - 3)(2x + 1) = 5(x - 3)$ by dividing both sides by $(x - 3)$ and got $x = 2$. Explain her mistake and solve the equation correctly.`, model: J([r`Dividing by $(x - 3)$ is allowed only when $x \ne 3$, so the root $x = 3$ is lost. Bring every term to one side instead:`, ...w406.md, r`Check: $x = 3$ makes both sides $0$; $x = 2$ makes both sides $-5$.`]), sol: 'Never divide by an expression that contains the unknown; take out the common factor instead.', scheme: [['Mistake explained (root x = 3 lost)', 1], ['All terms on one side', 1], ['Common factor taken out', 1], ['x = 3 or x = 2', 1]], d: 3, c: 'analysis', t: [2], time: 240 }), (C) => { w406.verify(C); C.assert((2 - 3) * (2 * 2 + 1) === -5 && 5 * (2 - 3) === -5 && (3 - 3) * 7 === 0, 'checks'); C.model([3, 2]); });
const S3 = Math.sqrt(3);
const c407 = ctxOf([1, 2 * S3, -9], [-3 * S3, S3]);
const w407 = W(c407, [r`x = \dfrac{-2\sqrt{3} \pm \sqrt{48}}{2} = \dfrac{-2\sqrt{3} \pm 4\sqrt{3}}{2}`, r`x = \sqrt{3} \text{ or } x = -3\sqrt{3}`, r`x \approx 1.73 \text{ or } x \approx -5.20`]);
const w407a = W(ARITH, [r`D = (2\sqrt{3})^2 - 4 \times 1 \times (-9) = 12 + 36 = 48`, r`\sqrt{48} = 4\sqrt{3}`]);
Q('s407', mk.short({ marks: 4, stem: r`Solve $x^2 + 2\sqrt{3}\,x - 9 = 0$. Give the roots in surd form and also correct to two decimal places.`, model: J([r`$a = 1$, $b = 2\sqrt{3}$, $c = -9$.`, ...w407a.md, ...w407.md]), sol: 'The formula works with surd coefficients too; simplify the square root of the discriminant to a multiple of the same surd.', scheme: [['D = 48', 1], ['Formula with correct substitution', 1], ['√3 and −3√3', 1], ['1.73 and −5.20', 1]], d: 4, c: 'application', t: [3], time: 300 }), (C) => { w407.verify(C); w407a.verify(C); for (const x of c407.roots) C.assert(Math.abs(x * x + 2 * S3 * x - 9) < 1e-12, `root ${x} substitutes to 0`); C.assert(3 + 2 * 3 - 9 === 0 && 27 - 18 - 9 === 0, 'exact substitution'); C.model([1.73, 5.2]); });

// =============================================================== long, 10 marks (3 + 3 + 4)
const el01a = Qd(6, -7, -20), el01 = Qd(3, -2, -6);
const wl01a = W(el01a, [r`6x^2 - 15x + 8x - 20 = 0`, r`3x(2x - 5) + 4(2x - 5) = 0`, r`(2x - 5)(3x + 4) = 0`, r`x = \dfrac{5}{2} \text{ or } x = -\dfrac{4}{3}`]);
const wl01b = W(ARITH, [r`D = (-2)^2 - 4 \times 3 \times (-6) = 4 + 72 = 76`, r`\sqrt{76} \approx 8.7178`, r`\dfrac{2 + 8.7178}{6} \approx 1.7863`, r`\dfrac{2 - 8.7178}{6} \approx -1.1196`]);
const wl01c = W(el01, [r`x = \dfrac{2 \pm \sqrt{76}}{6}`, r`x \approx 1.79 \text{ or } x \approx -1.12`]);
Q('l01', mk.long({ marks: 10, stem: 'Answer each part.\n(a) Solve by factorisation: $6x^2 - 7x - 20 = 0$.\n(b) Find the discriminant of $3x^2 - 2x - 6 = 0$ and hence state the nature of its roots.\n(c) Solve $3x^2 - 2x - 6 = 0$, giving the roots correct to two decimal places.', model: J([r`**(a)** Product $6 \times (-20) = -120$, sum $-7$: use $-15$ and $8$.`, ...wl01a.md, `**(b)** ${wl01b.md[0]}`, r`$76 > 0$ and $76$ is not a perfect square, so the roots are **real, distinct and irrational**.`, r`**(c)**`, wl01c.md[0], ...wl01b.md.slice(1), wl01c.md[1]]), sol: 'Part (a) splits the middle term; part (b) uses the sign of the discriminant and whether it is a perfect square; part (c) uses the formula and rounds at the end.', scheme: [['(a) middle term split and factorised', 2], ['(a) both roots', 1], ['(b) D = 76', 2], ['(b) real, distinct, irrational', 1], ['(c) formula with correct substitution', 2], ['(c) 1.79 and −1.12', 2]], d: 3, c: 'application', t: [1, 2, 3], time: 600 }), (C) => { wl01a.verify(C); wl01b.verify(C); wl01c.verify(C); C.assert(el01.D === 76 && !el01.rational && el01.nature === 'distinct', 'D = 76'); C.model([2.5, r`-\dfrac{4}{3}`, 76, 1.79, 1.12]); });
const kl02 = equalRootParams((k) => 4 * (k + 2) ** 2 - 36 * k);
const wl02k = W(Qd(1, -5, 4, 'k'), [r`(2(k + 2))^2 - 4 \times 9k = 0`, r`4(k + 2)^2 - 36k = 0`, r`k^2 - 5k + 4 = 0`, r`(k - 1)(k - 4) = 0`, r`k = 1 \text{ or } k = 4`]);
const wl02b1 = W(Qd(1, 6, 9), [r`x^2 + 6x + 9 = 0`, r`(x + 3)^2 = 0`, r`x = -3`]);
const wl02b2 = W(Qd(1, 12, 36), [r`x^2 + 12x + 36 = 0`, r`(x + 6)^2 = 0`, r`x = -6`]);
const el02c1 = Qd(1, 8, 18), el02c2 = Qd(1, 16, 54);
const wl02c = W(ARITH, [r`D = 8^2 - 4 \times 1 \times 18 = 64 - 72 = -8`, r`D = 16^2 - 4 \times 1 \times 54 = 256 - 216 = 40`, r`\sqrt{10} \approx 3.1623`, r`-8 + 3.1623 = -4.8377 \approx -4.84`, r`-8 - 3.1623 = -11.1623 \approx -11.16`]);
const wl02c2 = W(el02c2, [r`x^2 + 16x + 54 = 0`, r`x = \dfrac{-16 \pm \sqrt{40}}{2} = -8 \pm \sqrt{10}`, r`x \approx -4.84 \text{ or } x \approx -11.16`]);
Q('l02', mk.long({ marks: 10, stem: 'For the equation $x^2 + 2(k + 2)x + 9k = 0$:\n(a) find the values of $k$ for which the roots are equal;\n(b) find the equal root for each of these values of $k$;\n(c) show that the equation has no real roots when $k = 2$, and solve it when $k = 6$, giving the roots correct to two decimal places.', model: J([r`**(a)** $a = 1$, $b = 2(k + 2)$, $c = 9k$. Equal roots: $b^2 - 4ac = 0$.`, ...wl02k.md, r`**(b)** When $k = 1$:`, ...wl02b1.md, 'When $k = 4$:', ...wl02b2.md, r`**(c)** When $k = 2$ the equation is $x^2 + 8x + 18 = 0$:`, wl02c.md[0], r`$D < 0$, so there are no real roots. When $k = 6$:`, wl02c2.md[0], wl02c.md[1], wl02c2.md[1], ...wl02c.md.slice(2), wl02c2.md[2]]), sol: 'Set the discriminant (a quadratic in k) equal to zero; substitute each k back; for (c) compare the discriminant with zero and use the formula.', scheme: [['(a) discriminant in k set to zero', 2], ['(a) k = 1 or k = 4', 1], ['(b) k = 1: x = −3', 1], ['(b) k = 4: x = −6', 1], ['(b) perfect squares shown', 1], ['(c) k = 2: D = −8 < 0', 2], ['(c) k = 6: −4.84 and −11.16', 2]], d: 4, c: 'analysis', t: [1, 3], time: 720 }), (C) => { wl02k.verify(C); wl02b1.verify(C); wl02b2.verify(C); wl02c.verify(C); wl02c2.verify(C); C.assert(kl02.map((k) => k.val).join() === '1,4' && el02c1.nature === 'none' && el02c1.D === -8, 'k values; k = 2 has no real roots'); C.assert([[1, 6, 9], [4, 12, 36], [2, 8, 18], [6, 16, 54]].every(([k, b, c]) => 2 * (k + 2) === b && 9 * k === c), 'substituted coefficients'); C.model([1, 4, 3, 6, -8, 4.84, 11.16]); });
const el03 = Qd(1, 10, -16, 'w');
const wl03 = W(el03, [r`(12 + 2w)(8 + 2w) - 12 \times 8 = 64`, r`96 + 40w + 4w^2 - 96 = 64`, r`4w^2 + 40w - 64 = 0`, r`w^2 + 10w - 16 = 0`, r`w = \dfrac{-10 \pm \sqrt{164}}{2} = -5 \pm \sqrt{41}`]);
const wl03a = W(ARITH, [r`D = 10^2 - 4 \times 1 \times (-16) = 100 + 64 = 164`, r`\sqrt{41} \approx 6.4031`, r`-5 + 6.4031 = 1.4031 \approx 1.40`, r`-5 - 6.4031 = -11.4031`, r`2(12 + 2 \times 1.4031) + 2(8 + 2 \times 1.4031) = 40 + 8 \times 1.4031 = 51.2248 \approx 51`]);
const P03 = { scale: 0.5, w: el03.roots[1] };
const o3 = 0.5, W3 = P03.w * P03.scale;
const fig03 = geom({ width: 6 + 2 * W3 + 2 * o3, height: 4 + 2 * W3 + 2 * o3, points: { A: { at: [o3, o3], label: false }, B: { at: [o3 + 6 + 2 * W3, o3], label: false }, C: { at: [o3 + 6 + 2 * W3, o3 + 4 + 2 * W3], label: false }, D: { at: [o3, o3 + 4 + 2 * W3], label: false }, P: { at: [o3 + W3, o3 + W3], label: false }, Q: { at: [o3 + W3 + 6, o3 + W3], label: false }, R: { at: [o3 + W3 + 6, o3 + W3 + 4], label: false }, S: { at: [o3 + W3, o3 + W3 + 4], label: false }, U: { at: [o3 + W3 + 3, o3], label: false }, V: { at: [o3 + W3 + 3, o3 + W3], label: false } }, segments: [{ from: 'P', to: 'Q', label: '12 m' }, { from: 'Q', to: 'R', label: '8 m' }, { from: 'U', to: 'V', label: 'w' }], polygons: [{ vertices: ['A', 'B', 'C', 'D'], highlight: 'shade' }, { vertices: ['P', 'Q', 'R', 'S'], highlight: 'accent' }], scale: { unit: 'm', per_unit: P03.scale } }, 'A rectangular pond 12 metres by 8 metres, drawn as an inner rectangle, surrounded on all four sides by a shaded path of the same width w metres; the outer rectangle is the edge of the path.', 'Pond and path (to scale for the width found in (b)).');
Q('l03', mk.long({ marks: 10, stem: 'An imagined park has a rectangular pond $12$ m long and $8$ m wide. A path of uniform width $w$ m is laid all round the outside of the pond, and the area of the path is $64$ m².\n(a) Show that $w^2 + 10w - 16 = 0$.\n(b) Solve the equation to find the width of the path correct to two decimal places, giving a reason for rejecting one root.\n(c) The outer edge of the path is to be fenced. Find the length of fencing needed, correct to the nearest metre.', model: J([r`**(a)** The outer rectangle is $(12 + 2w)$ m by $(8 + 2w)$ m. Area of path = outer area $-$ pond area:`, ...wl03.md.slice(0, 4), r`**(b)**`, wl03a.md[0], wl03.md[4], ...wl03a.md.slice(1, 4), r`A width cannot be negative, so $w = -5 - \sqrt{41}$ is rejected. The path is about $1.40$ m wide.`, r`**(c)** Perimeter of the outer edge $= 2(12 + 2w) + 2(8 + 2w) = 40 + 8w$:`, wl03a.md[4], r`About $51$ m of fencing is needed.`]), sol: 'Area of the path is the outer rectangle minus the pond. Use the formula, keep the positive root, and substitute it in the outer perimeter.', scheme: [['(a) outer dimensions', 1], ['(a) area equation', 1], ['(a) simplified to w² + 10w − 16 = 0', 1], ['(b) formula with D = 164', 1], ['(b) w ≈ 1.40', 1], ['(b) negative root rejected', 1], ['(c) perimeter 40 + 8w', 2], ['(c) 51 m', 2]], d: 4, c: 'application', t: [4, 3], time: 720, assets: [fig03] }), (C) => { wl03.verify(C); wl03a.verify(C); C.assert(dp(el03.roots[1], 2) === '1.40' && near(el03.roots[1], -5 + Math.sqrt(41)) && Math.round(40 + 8 * el03.roots[1]) === 51 && near(40 + 8 * el03.roots[1], 8 * Math.sqrt(41)), 'w and perimeter (exact and rounded agree)'); C.assert(near((12 + 2 * el03.roots[1]) * (8 + 2 * el03.roots[1]) - 96, 64), 'story'); C.model([1.4, 51, 164]); });
const el04 = Qd(3, -56, 128);
const wl04 = W(el04, [r`\dfrac{24}{x} + \dfrac{9}{x - 4} = \dfrac{9}{4}`, r`96(x - 4) + 36x = 9x(x - 4)`, r`132x - 384 = 9x^2 - 36x`, r`9x^2 - 168x + 384 = 0`, r`3x^2 - 56x + 128 = 0`, r`3x^2 - 48x - 8x + 128 = 0`, r`3x(x - 16) - 8(x - 16) = 0`, r`(x - 16)(3x - 8) = 0`, r`x = 16 \text{ or } x = \dfrac{8}{3}`]);
const wl04c = W(ARITH, [r`\dfrac{24}{16} = 1.5`, r`\dfrac{9}{12} = 0.75`, r`1.5 + 0.75 = 2.25`, r`\dfrac{33}{2.25} \approx 14.67`]);
Q('l04', mk.long({ marks: 10, stem: 'An imagined cyclist rides $24$ km on a flat road at $x$ km/h and then $9$ km up a hill at $4$ km/h less than her speed on the flat. The whole ride takes $2\\tfrac{1}{4}$ hours.\n(a) Show that $3x^2 - 56x + 128 = 0$.\n(b) Solve the equation and find her speed on the flat, giving a reason for rejecting one root.\n(c) Find the time taken for each part of the ride and her average speed for the whole ride, correct to two decimal places.', model: J([r`**(a)** Time on the flat $= \dfrac{24}{x}$ h; time on the hill $= \dfrac{9}{x - 4}$ h; total $\dfrac{9}{4}$ h.`, wl04.md[0], 'Multiply both sides by $4x(x - 4)$:', ...wl04.md.slice(1, 5), r`**(b)** Product $3 \times 128 = 384$, sum $-56$: use $-48$ and $-8$.`, ...wl04.md.slice(5), r`If $x = \dfrac{8}{3}$, the hill speed $\dfrac{8}{3} - 4$ would be negative, so it is rejected. Her speed on the flat is $16$ km/h (and $12$ km/h up the hill).`, `**(c)** Time on the flat: ${wl04c.md[0]} hours. Time on the hill: ${wl04c.md[1]} hours. Total time: ${wl04c.md[2]} hours for $24 + 9 = 33$ km.`, `Average speed: ${wl04c.md[3]} km/h.`]), sol: 'Time = distance ÷ speed for each stretch; clear the fractions, factorise, and reject the root that makes a speed negative; average speed is total distance over total time.', scheme: [['(a) time terms', 1], ['(a) fractions cleared', 1], ['(a) simplified to 3x² − 56x + 128 = 0', 1], ['(b) factorised', 1], ['(b) x = 16 or 8/3', 1], ['(b) 8/3 rejected; 16 km/h', 1], ['(c) 1.5 h on the flat', 1], ['(c) 0.75 h on the hill', 1], ['(c) 33 km in 2.25 h', 1], ['(c) 14.67 km/h', 1]], d: 4, c: 'application', t: [4], time: 720 }), (C) => { wl04.verify(C); wl04c.verify(C); C.assert(near(24 / 16 + 9 / 12, 9 / 4) && 8 / 3 - 4 < 0, 'story; 8/3 rejected'); C.model([16, 1.5, 0.75, 14.67]); });
const el05a = Qd(1, -16, -80), el05b = Qd(1, -3, -70, 'n'), el05c = Qd(1, -3, -60, 'n');
const wl05a = W(el05a, [r`x^2 + (x + 1)^2 = (x + 9)^2`, r`2x^2 + 2x + 1 = x^2 + 18x + 81`, r`x^2 - 16x - 80 = 0`, r`(x - 20)(x + 4) = 0`, r`x = 20 \text{ or } x = -4`]);
const wl05b = W(el05b, [r`\dfrac{n(n - 3)}{2} = 35`, r`n^2 - 3n - 70 = 0`, r`(n - 10)(n + 7) = 0`, r`n = 10 \text{ or } n = -7`]);
const wl05c = W(el05c, [r`\dfrac{n(n - 3)}{2} = 30`, r`n^2 - 3n - 60 = 0`]);
const wl05d = W(ARITH, [r`D = (-3)^2 - 4 \times 1 \times (-60) = 9 + 240 = 249`, r`\dfrac{9 \times 6}{2} = 27`, r`\dfrac{10 \times 7}{2} = 35`]);
Q('l05', mk.long({ marks: 10, stem: 'Answer each part.\n(a) The sides of a right-angled triangle are $x$ cm, $(x + 1)$ cm and $(x + 9)$ cm, the longest being the hypotenuse. Find $x$ and the three sides.\n(b) A polygon with $n$ sides has $\\dfrac{n(n - 3)}{2}$ diagonals. How many sides has a polygon with $35$ diagonals?\n(c) Using the formula in (b), decide whether a polygon can have exactly $30$ diagonals. Justify your answer.', model: J([r`**(a)** By Pythagoras' theorem:`, ...wl05a.md, r`A side cannot be negative, so $x = 20$: the sides are $20$ cm, $21$ cm and $29$ cm (check: $400 + 441 = 841 = 29^2$).`, r`**(b)**`, ...wl05b.md, r`$n$ must be a natural number, so the polygon has $10$ sides.`, r`**(c)**`, ...wl05c.md, wl05d.md[0], r`$249$ is not a perfect square ($15^2 = 225$, $16^2 = 256$), so the roots are irrational and $n$ cannot be a natural number. No polygon has exactly $30$ diagonals.`, `Indeed, a nonagon has ${wl05d.md[1]} diagonals and a decagon has ${wl05d.md[2]}, so $30$ is skipped.`]), sol: 'Each part leads to a quadratic: keep only roots that are valid lengths or counts; in (c) a non-square discriminant means no whole-number solution.', scheme: [['(a) Pythagoras equation', 1], ['(a) x = 20 (−4 rejected)', 1], ['(a) sides 20, 21, 29 cm', 1], ['(b) n² − 3n − 70 = 0', 1], ['(b) n = 10 or −7', 1], ['(b) 10 sides', 1], ['(c) n² − 3n − 60 = 0', 1], ['(c) D = 249', 1], ['(c) not a perfect square, so n is not natural', 1], ['(c) conclusion: not possible', 1]], d: 4, c: 'analysis', t: [4, 1], time: 720 }), (C) => { wl05a.verify(C); wl05b.verify(C); wl05c.verify(C); wl05d.verify(C); W(ARITH, [r`400 + 441 = 841 = 29^2`]).verify(C); C.assert(20 ** 2 + 21 ** 2 === 29 ** 2 && el05c.D === 249 && !el05c.rational && 15 ** 2 < 249 && 249 < 16 ** 2, 'triangle; 249 not square'); C.model([20, 21, 29, 10, 249]); });
